CREATE TABLE "tblTransaction"
(
    "Id"           BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ExternalId"   UUID                                    NOT NULL,
    "CustomerId"   BIGINT                                  NOT NULL,
    "OccurredAt"   TIMESTAMP WITH TIME ZONE                NOT NULL,
    "Merchant"     VARCHAR(100)                            NOT NULL,
    "Description"  VARCHAR(200)                            NOT NULL,
    "AmountMinor"  BIGINT                                  NOT NULL,
    "CurrencyCode" CHAR(3)                                 NOT NULL,
    "State"        VARCHAR(100)                            NOT NULL,

    CONSTRAINT "PK_Transaction" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Transaction_ExternalId" UNIQUE ("ExternalId"),
    CONSTRAINT "FK_Transaction_Customer" FOREIGN KEY ("CustomerId") REFERENCES "tblCustomer" ("Id"),
    CONSTRAINT "FK_Transaction_Currency" FOREIGN KEY ("CurrencyCode") REFERENCES "lupCurrency" ("Code")
);

CREATE INDEX "IX_Transaction_CustomerIdOccurredAtId" ON "tblTransaction" ("CustomerId", "OccurredAt" DESC, "Id" DESC);
